// titlePokeRecord is one Deps.OnTitleChange invocation: the entity id, the
// context liveness, and what the store read back for that id at poke time —
// found (the override row), cleared (sql.ErrNoRows), or neither.
type titlePokeRecord struct {
	entityID    string
	hasCtx      bool
	readbackErr error
}

// TestTitleOverridePoke covers the title-change invalidation seam
// (browse-scale 3.4) on the title-override routes: with Deps.OnTitleChange
// wired, putTitle and deleteTitle each invoke it exactly once with the target
// entity id — after the confirmed store write (PUT: the closure reads the NEW
// override back; DELETE: the row is already gone) and before the response
// write (doRequest is synchronous, so the closure has run by the time the
// response is observed); the rejected paths (validation 400, unknown id 404)
// stay silent, and with the closure nil the responses are unchanged.
func TestTitleOverridePoke(t *testing.T) {
	t.Run("put_fires_per_entity_after_the_write", func(t *testing.T) {
		st := openAPIStore(t)
		ctx := context.Background()
		libID, err := st.CreateLibrary(ctx, "serial", "/media/titlepoke", "TitlePoke")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		series := seedSeries(t, st, libID, "Show",
			`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`, "ready")
		seedItem(t, st, libID, "ep1", "Show/Show S01E01.mkv")

		var records []titlePokeRecord
		h := New(Deps{
			AdminToken: adminToken,
			Store:      st,
			Scan:       func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
			OnTitleChange: func(pokeCtx context.Context, entityID string) {
				_, rerr := st.GetTitleOverride(pokeCtx, entityID)
				records = append(records, titlePokeRecord{entityID: entityID, hasCtx: pokeCtx != nil, readbackErr: rerr})
			},
		})

		// PUT a series override: exactly one poke, with the series id, the
		// request context, and the row ALREADY stored (poke after the write).
		resp := doRequest(t, h, http.MethodPut, "/api/v1/series/"+series.ID+"/title", `{"title":"Better Name"}`, adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("series PUT status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if len(records) != 1 {
			t.Fatalf("OnTitleChange calls = %d, want exactly 1 after the series PUT", len(records))
		}
		rec := records[0]
		if rec.entityID != series.ID {
			t.Fatalf("poke entity id = %q, want %q", rec.entityID, series.ID)
		}
		if !rec.hasCtx {
			t.Fatal("poke received a nil context, want the request context")
		}
		if rec.readbackErr != nil {
			t.Fatalf("poke fired before the store write — GetTitleOverride: %v", rec.readbackErr)
		}

		// PUT an item override: a second poke, with the item id (per-entity).
		putTitle(t, h, "/api/v1/items/itm_ep1/title", `{"title":"Ep Renamed"}`, adminToken, http.StatusOK, "")
		if len(records) != 2 {
			t.Fatalf("OnTitleChange calls = %d, want 2 after the item PUT", len(records))
		}
		if records[1].entityID != "itm_ep1" || records[1].readbackErr != nil {
			t.Fatalf("item poke = %+v, want itm_ep1 with the row stored", records[1])
		}
	})

	t.Run("delete_fires_after_the_clear", func(t *testing.T) {
		st := openAPIStore(t)
		ctx := context.Background()
		libID, err := st.CreateLibrary(ctx, "serial", "/media/titlepoke-del", "TitlePokeDel")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		series := seedSeries(t, st, libID, "Show",
			`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`, "ready")

		var records []titlePokeRecord
		h := New(Deps{
			AdminToken: adminToken,
			Store:      st,
			Scan:       func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
			OnTitleChange: func(pokeCtx context.Context, entityID string) {
				_, rerr := st.GetTitleOverride(pokeCtx, entityID)
				records = append(records, titlePokeRecord{entityID: entityID, hasCtx: pokeCtx != nil, readbackErr: rerr})
			},
		})

		putTitle(t, h, "/api/v1/series/"+series.ID+"/title", `{"title":"X"}`, adminToken, http.StatusOK, "")
		resp := doRequest(t, h, http.MethodDelete, "/api/v1/series/"+series.ID+"/title", "", adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("DELETE status = %d, want %d", resp.StatusCode, http.StatusNoContent)
		}
		if len(records) != 2 {
			t.Fatalf("OnTitleChange calls = %d, want 2 (PUT + DELETE)", len(records))
		}
		if records[1].entityID != series.ID || !records[1].hasCtx {
			t.Fatalf("delete poke = %+v, want the series id with the request context", records[1])
		}
		if !errors.Is(records[1].readbackErr, sql.ErrNoRows) {
			t.Fatalf("delete poke read back %v, want sql.ErrNoRows — the poke fired before the clear", records[1].readbackErr)
		}

		// The idempotent no-row delete fires too: the store clear is
		// unconditional, and a clear may have restored a composed name.
		resp = doRequest(t, h, http.MethodDelete, "/api/v1/series/"+series.ID+"/title", "", adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("idempotent DELETE status = %d, want %d", resp.StatusCode, http.StatusNoContent)
		}
		if len(records) != 3 {
			t.Fatalf("OnTitleChange calls = %d, want 3 (the no-row delete fires too)", len(records))
		}
	})

	t.Run("rejected_paths_stay_silent", func(t *testing.T) {
		st := openAPIStore(t)
		ctx := context.Background()
		libID, err := st.CreateLibrary(ctx, "serial", "/media/titlepoke-silent", "TitlePokeSilent")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		series := seedSeries(t, st, libID, "Show",
			`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`, "ready")

		var pokes int
		h := New(Deps{
			AdminToken: adminToken,
			Store:      st,
			Scan:       func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
			OnTitleChange: func(context.Context, string) {
				pokes++
			},
		})

		// Validation 400 and unknown-id 404 write nothing, so they poke
		// nothing.
		putTitle(t, h, "/api/v1/series/"+series.ID+"/title", `{"title":"   "}`, adminToken, http.StatusBadRequest, "bad_request")
		putTitle(t, h, "/api/v1/series/ser_999_deadbeefdeadbeef/title", `{"title":"X"}`, adminToken, http.StatusNotFound, "not_found")
		resp := doRequest(t, h, http.MethodDelete, "/api/v1/series/ser_999_deadbeefdeadbeef/title", "", adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("unknown-id DELETE status = %d, want %d", resp.StatusCode, http.StatusNoContent)
		}
		// NOTE: that DELETE succeeded (the clear is unconditional), so it IS
		// a poke — rewind the counter and assert only the rejections stayed
		// silent.
		if pokes != 1 {
			t.Fatalf("pokes = %d, want exactly 1 (the unconditional no-row DELETE)", pokes)
		}
	})

	t.Run("nil_closure_is_a_noop", func(t *testing.T) {
		h, _, _, seriesID, _ := newTitleAPI(t)
		putTitle(t, h, "/api/v1/series/"+seriesID+"/title", `{"title":"X"}`, adminToken, http.StatusOK, "")
		resp := doRequest(t, h, http.MethodDelete, "/api/v1/series/"+seriesID+"/title", "", adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("DELETE status = %d, want %d", resp.StatusCode, http.StatusNoContent)
		}
	})
}

// TestIdentifyPoke covers the title-change invalidation seam (browse-scale
// 3.4) on the identify route: with Deps.OnTitleChange wired, a successful
// seriesIdentify invokes it exactly once with the re-anchored series id —
// after the IdentifySeries closure (the anchor may rename the composed title)
// and before the response write; the rejected paths (unknown series 404,
// empty source_id 400 with the closure never called) stay silent.
func TestIdentifyPoke(t *testing.T) {
	t.Run("fires_after_the_anchor_on_accept", func(t *testing.T) {
		// The shared sequence pins the order: the re-anchor closure first,
		// the poke second.
		var seq []string
		var pokeEntityID string
		var pokeHasCtx bool
		h := New(Deps{
			AdminToken: adminToken,
			Store:      openAPIStore(t),
			IdentifySeries: func(context.Context, string, string, string) (bool, int, int, error) {
				seq = append(seq, "identify")
				return true, 2, 0, nil
			},
			OnTitleChange: func(ctx context.Context, entityID string) {
				seq = append(seq, "poke")
				pokeEntityID = entityID
				pokeHasCtx = ctx != nil
			},
		})

		resp := doRequest(t, h, http.MethodPut, "/api/v1/series/ser_abc/identify", `{"source_id":"shikimori","external_id":"378"}`, adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusAccepted {
			t.Fatalf("identify status = %d, want %d", resp.StatusCode, http.StatusAccepted)
		}
		if len(seq) != 2 || seq[0] != "identify" || seq[1] != "poke" {
			t.Fatalf("sequence = %v, want [identify poke] — the poke follows the anchor", seq)
		}
		if pokeEntityID != "ser_abc" {
			t.Fatalf("poke entity id = %q, want ser_abc", pokeEntityID)
		}
		if !pokeHasCtx {
			t.Fatal("poke received a nil context, want the request context")
		}
	})

	t.Run("rejected_paths_stay_silent", func(t *testing.T) {
		var pokes int
		var identifyCalls int
		h := New(Deps{
			AdminToken: adminToken,
			Store:      openAPIStore(t),
			IdentifySeries: func(context.Context, string, string, string) (bool, int, int, error) {
				identifyCalls++
				return false, 0, 0, fmt.Errorf("enrich: identify: load series: %w", sql.ErrNoRows)
			},
			OnTitleChange: func(context.Context, string) {
				pokes++
			},
		})

		// Unknown series → 404, the anchor never landed: no poke.
		resp := doRequest(t, h, http.MethodPut, "/api/v1/series/ser_abc/identify", `{"source_id":"shikimori","external_id":"378"}`, adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("unknown-series status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		// Empty source_id → 400 before the closure runs.
		resp = doRequest(t, h, http.MethodPut, "/api/v1/series/ser_abc/identify", `{"source_id":"","external_id":"378"}`, adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("empty source_id status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if identifyCalls != 1 {
			t.Fatalf("IdentifySeries calls = %d, want 1 (the 400 never reaches the closure)", identifyCalls)
		}
		if pokes != 0 {
			t.Fatalf("pokes = %d, want 0 on the rejected paths", pokes)
		}
	})

	t.Run("nil_closure_is_a_noop", func(t *testing.T) {
		h := New(Deps{
			AdminToken: adminToken,
			Store:      openAPIStore(t),
			IdentifySeries: func(context.Context, string, string, string) (bool, int, int, error) {
				return true, 1, 0, nil
			},
		})
		resp := doRequest(t, h, http.MethodPut, "/api/v1/series/ser_abc/identify", `{"source_id":"shikimori","external_id":"378"}`, adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusAccepted {
			t.Fatalf("identify status = %d, want %d", resp.StatusCode, http.StatusAccepted)
		}
	})
}
